import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:yoclip_core/yoclip_core.dart';

void main() {
  final outputPath = Platform.environment['YOCLIP_OUTPUT'];

  final externalImageBytes = <String, Uint8List>{
    for (final e in {"logo":""}.entries)
      e.key: base64Decode(e.value as String),
  };

  testWidgets(
    'yoclip render-pptx',
    (tester) async {
      if (outputPath == null) return;
      final defaultFlutterError = FlutterError.onError;
      FlutterError.onError = (details) {
        final exception = details.exception;
        if (exception is FlutterError && exception.toString().contains('overflowed by')) {
          // Some projects intentionally use oversized text rows/columns; don't
          // fail the export because of debug-only overflow indicators.
          return;
        }
        defaultFlutterError?.call(details);
      };
      addTearDown(() => FlutterError.onError = defaultFlutterError);

      const projectPath = '/Users/Uladzimir_Klyshevich/git/yoclip/samples/yoclip_intro';

      final storage = LocalFileSystemStorage(projectPath);
      final project = await YoclipProject.load(storage, projectPath);

      final runtime = YoclipQuickJsRuntime();
      await runtime.init();
      addTearDown(runtime.dispose);

      final scenes = await loadYoclipProjectScenes(runtime, project, storage);

      final renderProject = resolveYoclipAutoDuration(project, scenes);
      final adjustedProject = YoclipProject(
        rootPath: renderProject.rootPath,
        config: YoclipProjectConfig(
          duration: renderProject.config.autoDuration
              ? renderProject.config.duration
              : 90,
          fps: 30,
          width: 1920,
          height: 1080,
          background: renderProject.config.background,
          theme: renderProject.config.theme,
          overlay: renderProject.config.overlay,
        ),
        externalAssets: renderProject.externalAssets,
        scenePaths: renderProject.scenePaths,
        pluginPaths: renderProject.pluginPaths,
        fonts: renderProject.fonts,
      );

      await yoclipLoadProjectFonts(storage, adjustedProject.fonts);

      final fontBytes = <String, Uint8List>{
        for (final font in adjustedProject.fonts)
          if (File('$projectPath/' + font.path).existsSync())
            font.family: File('$projectPath/' + font.path).readAsBytesSync(),
      };

      final renderer = HeadlessPptxSceneRenderer(
        tester: tester,
        width: 1920.0,
        height: 1080.0,
      );

      final exporter = PptxSceneExporter(
        project: adjustedProject,
        config: VideoConfig(
          duration: adjustedProject.config.duration,
          fps: adjustedProject.config.fps,
          width: adjustedProject.config.width,
          height: adjustedProject.config.height,
        ),
        renderer: renderer,
        assets: YoclipExternalAssets(
          files: {"laptop_open":"/Users/Uladzimir_Klyshevich/git/yoclip/samples/yoclip_intro/.yoclip_cache/external/laptop_open/laptop_open.mp4","logo":"/Users/Uladzimir_Klyshevich/git/yoclip/samples/yoclip_intro/.yoclip_cache/external/logo/1780588269066.png"},
          frameDirs: {"laptop_open":"/Users/Uladzimir_Klyshevich/git/yoclip/samples/yoclip_intro/.yoclip_cache/external/laptop_open/frames"},
          imageBytes: externalImageBytes,
          child: const SizedBox.shrink(),
        ),
        fontBytes: fontBytes,
        options: const YoclipPptxExportOptions(
          editableText: true,
          gifPatches: false,
          entranceAnimations: false,
        ),
      );

      final bytes = await exporter.export(scenes);
      File(outputPath).writeAsBytesSync(bytes);

      final outputFile = File(outputPath);
      expect(outputFile.existsSync(), isTrue);
      expect(outputFile.lengthSync(), greaterThan(1000));
    },
    skip: outputPath == null,
  );
}
